app.get(MAIN_APP_ROUTES, (req, res) => {
  res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
  res.setHeader('Pragma', 'no-cache');
  res.setHeader('Expires', '0');
  res.setHeader('Content-Type', 'text/html; charset=utf-8');

  let html = loadBaseHtml();
  const rawLang = String(req.query.lang || '').toLowerCase();
  const lang = ['en', 'de', 'fr', 'es'].includes(rawLang) ? rawLang : 'en';
  const reqPath = req.path === '/index.html' ? '/' : req.path;

  const metaObj = (SEO_ROUTE_META[reqPath] && SEO_ROUTE_META[reqPath][lang])
    ? SEO_ROUTE_META[reqPath][lang]
    : (HOME_LANG_META[lang] || HOME_LANG_META.en);

  const canonicalUrl = `https://anyvid.app${reqPath}${rawLang && ['en', 'de', 'fr', 'es'].includes(rawLang) ? '?lang=' + rawLang : ''}`;

  html = html
    .replace('<html lang="en"', `<html lang="${lang}"`)
    .replace(/<title>[\s\S]*?<\/title>/, `<title>${metaObj.title}</title>`)
    .replace(/<meta name="description" content="[^"]*">/, `<meta name="description" content="${metaObj.desc}">`)
    .replace(/<link rel="canonical" id="canonicalLink" href="[^"]*">/, `<link rel="canonical" id="canonicalLink" href="${canonicalUrl}">`);

  return res.send(html);
});

